// La règle vit dans le type : un Money négatif est impossible à construire
record Money(double montant, String devise) {
    Money {
        if (montant < 0) {
            throw new IllegalArgumentException("montant negatif : " + montant);
        }
    }
}

class CalculateurTva {
    private static final double TAUX_TVA = 0.20;

    Money tva(Money base) {
        return new Money(base.montant() * TAUX_TVA, base.devise());
    }
}
